def validate_office_controlled_mutation_manual_runtime_command_execution_record(payload: object, *, source_inclusion: Mapping[str, object]) -> dict[str, object]:
    errors: list[dict[str, str]] = []
    if not isinstance(payload, Mapping):
        return {"valid": False, "errors": [_error("payload", "invalid_payload_type")], "dto": None}
    for field in sorted(_RUNTIME_COMMAND_EXECUTION_RECORD_FIELDS):
        if field not in payload:
            errors.append(_error(field, "required"))
    if "runtime_command_ref" in payload and not _office_disabled_runtime_dispatch_valid_prefixed_ref(payload.get("runtime_command_ref"), "cmd-"):
        errors.append(_error("runtime_command_ref", "unsupported_ref_shape"))
    if "runtime_command_ref" in payload and payload.get("runtime_command_ref") != source_inclusion.get("runtime_command_ref"):
        errors.append(_error("runtime_command_ref", "runtime_command_mismatch"))
    if "runtime_execution_ref" in payload and not _office_disabled_runtime_dispatch_valid_prefixed_ref(payload.get("runtime_execution_ref"), "exec-"):
        errors.append(_error("runtime_execution_ref", "unsupported_ref_shape"))
    if "idempotency_key" in payload and not _office_disabled_runtime_dispatch_valid_prefixed_ref(payload.get("idempotency_key"), "idem-"):
        errors.append(_error("idempotency_key", "unsupported_ref_shape"))
    if "operator_confirmation" in payload and payload.get("operator_confirmation") != "confirmed-runtime-command-execute-noop-probe-only":
        errors.append(_error("operator_confirmation", "unsupported_confirmation"))
    if "executed_by" in payload and not _is_opaque_ref(payload.get("executed_by")):
        errors.append(_error("executed_by", "invalid_opaque_ref"))
    if "executed_at" in payload and not (isinstance(payload.get("executed_at"), str) and _ISO_UTC_RE.fullmatch(payload["executed_at"])):
        errors.append(_error("executed_at", "invalid_timestamp"))
    if "execution_evidence_refs" in payload and not _validate_evidence_refs(payload.get("execution_evidence_refs")):
        errors.append(_error("execution_evidence_refs", "invalid_opaque_ref"))
    if source_inclusion.get("command_kind") != "office_controlled_mutation_single_dispatch_noop_probe":
        errors.append(_error("command_kind", "unsupported_command_kind"))
    if not bool(source_inclusion.get("runtime_command_included")):
        errors.append(_error("runtime_command_ref", "runtime_command_not_included"))
    if errors:
        return {"valid": False, "errors": errors, "dto": None}
    dto = {
        "schema_version": 1,
        "mode": "stored_manual_runtime_command_execution_record",
        "execution_status": "noop_probe_executed_no_target_mutation",
        "runtime_command_preview_ref": source_inclusion.get("runtime_command_preview_ref"),
        "runtime_command_ref": payload["runtime_command_ref"],
        "runtime_execution_ref": payload["runtime_execution_ref"],
        "idempotency_key": payload["idempotency_key"],
        "dispatch_gate_ref": source_inclusion.get("dispatch_gate_ref"),
        "approval_record_ref": source_inclusion.get("approval_record_ref"),
        "command_envelope_ref": source_inclusion.get("command_envelope_ref"),
        "command_intent_ref": source_inclusion.get("command_intent_ref"),
        "command_kind": source_inclusion.get("command_kind"),
        "command_body_checksum_sha256": source_inclusion.get("runtime_command_body_checksum_sha256"),
        "executed_by": payload["executed_by"],
        "executed_at": payload["executed_at"],
        "execution_evidence_refs": list(payload["execution_evidence_refs"]),
        "runtime_execution_result": "noop_probe_succeeded",
        "approval_record_written": True,
        "dispatch_gate_open": True,
        "runtime_command_preview_created": True,
        "runtime_command_included": True,
        "runtime_command_executed": True,
        "adapter_binding_created": False,
        "adapter_dispatch_created": False,
        "idempotency_replay_store_written": True,
        "rollback_executed": False,
        "target_mutation_created": False,
        "watcher_or_cron_created": False,
        "kanban_mutation_created": False,
        "nas_save_created": False,
        "vps_file_change_created": False,
        "real_dispatch_execution_enabled": False,
        "capabilities": _runtime_command_execution_record_capabilities(),
        "redaction": {
            "shell_command_excluded": True,
            "provider_excluded": True,
            "credentials_echoed": False,
            "unsupported_values_echoed": False,
            "safe_noop_probe_only": True,
        },
    }
    return {"valid": True, "errors": [], "dto": dto}


def _normalize_stored_runtime_command_execution_record(item: object) -> dict[str, object] | None:
    if not isinstance(item, Mapping):
        return None
    if item.get("mode") != "stored_manual_runtime_command_execution_record":
        return None
    if not _office_disabled_runtime_dispatch_valid_prefixed_ref(item.get("runtime_command_ref"), "cmd-"):
        return None
    if not _office_disabled_runtime_dispatch_valid_prefixed_ref(item.get("runtime_execution_ref"), "exec-"):
        return None
    if not _office_disabled_runtime_dispatch_valid_prefixed_ref(item.get("idempotency_key"), "idem-"):
        return None
    if item.get("runtime_execution_result") != "noop_probe_succeeded":
        return None
    return dict(item)


def _read_runtime_command_execution_record_store(path: Path) -> tuple[list[dict[str, object]], int]:
    records: list[dict[str, object]] = []
    skipped_count = 0
    if not path.exists():
        return records, skipped_count
    with path.open("r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            try:
                item = json.loads(line)
            except json.JSONDecodeError:
                skipped_count += 1
                continue
            normalized = _normalize_stored_runtime_command_execution_record(item)
            if normalized is None:
                skipped_count += 1
                continue
            records.append(normalized)
    return records, skipped_count


def append_office_controlled_mutation_manual_runtime_command_execution_record(
    payload: object, *, inclusion_store_path: Path | None = None, store_path: Path | None = None
) -> dict[str, object]:
    if not isinstance(payload, Mapping):
        return {"stored": False, "errors": [_error("payload", "invalid_payload_type")], "dto": None}
    runtime_command_ref = payload.get("runtime_command_ref")
    if not _office_disabled_runtime_dispatch_valid_prefixed_ref(runtime_command_ref, "cmd-"):
        return {"stored": False, "errors": [_error("runtime_command_ref", "unsupported_ref_shape")], "dto": None}
    inclusion_readback = list_office_controlled_mutation_manual_runtime_command_inclusion_records(
        store_path=inclusion_store_path,
        runtime_command_ref=cast(str, runtime_command_ref),
        limit=1,
    )
    inclusions = cast(list[dict[str, object]], inclusion_readback.get("records", []))
    if not inclusions:
        return {"stored": False, "errors": [_error("runtime_command_ref", "runtime_command_inclusion_not_found")], "dto": None}
    validation = validate_office_controlled_mutation_manual_runtime_command_execution_record(payload, source_inclusion=inclusions[-1])
    if not validation["valid"]:
        return {"stored": False, "errors": validation["errors"], "dto": None}
    dto = cast(dict[str, object], validation["dto"])
    path = store_path or _default_runtime_command_execution_record_store_path()
    existing, _ = _read_runtime_command_execution_record_store(path)
    if any(item.get("runtime_execution_ref") == dto["runtime_execution_ref"] for item in existing):
        return {"stored": False, "errors": [_error("runtime_execution_ref", "duplicate_runtime_execution_ref")], "dto": None}
    if any(item.get("idempotency_key") == dto["idempotency_key"] for item in existing):
        return {"stored": False, "errors": [_error("idempotency_key", "duplicate_idempotency_key")], "dto": None}
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(dto, sort_keys=True, separators=(",", ":")) + "\n")
    return {"stored": True, "errors": [], "dto": dto}


