def append_office_controlled_mutation_nas_keeper_fresh_request_builder_ledger_downstream_consumption_exact_approval_record(
    payload: object,
    *,
    consumption_enablement_store_path: Path | None = None,
    store_path: Path | None = None,
) -> dict[str, object]:
    if not isinstance(payload, Mapping):
        return {"stored": False, "errors": [_error("payload", "invalid_payload_type")], "dto": None}
    design = get_office_controlled_mutation_nas_keeper_fresh_request_builder_ledger_downstream_consumption_one_shot_boundary_design(
        consumption_enablement_store_path=consumption_enablement_store_path,
    )
    source = design.get("dto") if isinstance(design.get("dto"), Mapping) else None
    source_map = cast(Mapping[str, object], source) if isinstance(source, Mapping) else {}
    errors: list[dict[str, str]] = []
    if not source or not design.get("found") or source_map.get("boundary_design_ready") is not True:
        errors.append(_error("boundary_design", "boundary_design_not_ready"))
    if not _office_disabled_runtime_dispatch_valid_prefixed_ref(payload.get("exact_approval_ref"), "exactapproval-"):
        errors.append(_error("exact_approval_ref", "unsupported_ref_shape"))
    if payload.get("selection_profile") != "latest_written":
        errors.append(_error("selection_profile", "unsupported_selection_profile"))
    for field in ("source_consumption_enablement_record_sha256", "boundary_design_sha256"):
        value = payload.get(field)
        expected = source_map.get(field)
        if not (isinstance(value, str) and re.fullmatch(r"[0-9a-f]{64}", value)):
            errors.append(_error(field, "invalid_sha256"))
        elif value != expected:
            errors.append(_error(field, "boundary_design_mismatch"))
    if not _office_disabled_runtime_dispatch_valid_prefixed_ref(payload.get("source_consumption_enablement_ref"), "consumptionenable-"):
        errors.append(_error("source_consumption_enablement_ref", "unsupported_ref_shape"))
    elif payload.get("source_consumption_enablement_ref") != source_map.get("source_consumption_enablement_ref"):
        errors.append(_error("source_consumption_enablement_ref", "boundary_design_mismatch"))
    if not _is_opaque_id(payload.get("approved_by")):
        errors.append(_error("approved_by", "invalid_opaque_ref"))
    if not (isinstance(payload.get("approved_at"), str) and _ISO_UTC_RE.fullmatch(str(payload.get("approved_at")))):
        errors.append(_error("approved_at", "invalid_timestamp"))
    if payload.get("operator_confirmation") != "confirmed-approve-one-shot-downstream-consumption-boundary-only":
        errors.append(_error("operator_confirmation", "unsupported_confirmation"))
    if not _is_safe_text(payload.get("safe_summary")):
        errors.append(_error("safe_summary", "invalid_safe_text"))
    if not _validate_evidence_refs(payload.get("evidence_refs")):
        errors.append(_error("evidence_refs", "invalid_opaque_ref"))
    path = store_path or _default_fresh_request_builder_downstream_consumption_exact_approval_record_store_path()
    existing, _ = _read_fresh_request_builder_downstream_consumption_exact_approval_records(path)
    if any(record.get("exact_approval_ref") == payload.get("exact_approval_ref") for record in existing):
        errors.append(_error("exact_approval_ref", "duplicate_exact_approval_ref"))
    if any(record.get("boundary_design_sha256") == payload.get("boundary_design_sha256") for record in existing):
        errors.append(_error("boundary_design_sha256", "duplicate_boundary_design_approval"))
    errors = sorted(errors, key=lambda item: (item["field"], item["code"]))
    if errors:
        deduped: list[dict[str, str]] = []
        seen: set[tuple[str, str]] = set()
        for error in errors:
            key = (error["field"], error["code"])
            if key not in seen:
                seen.add(key)
                deduped.append(error)
        return {"stored": False, "errors": deduped, "dto": None}
    record_material = {
        "exact_approval_ref": payload.get("exact_approval_ref"),
        "selection_profile": "latest_written",
        "source_consumption_enablement_ref": payload.get("source_consumption_enablement_ref"),
        "source_consumption_enablement_record_sha256": payload.get("source_consumption_enablement_record_sha256"),
        "boundary_design_sha256": payload.get("boundary_design_sha256"),
        "approved_by": payload.get("approved_by"),
        "approved_at": payload.get("approved_at"),
        "operator_confirmation": "confirmed-approve-one-shot-downstream-consumption-boundary-only",
        "safe_summary": payload.get("safe_summary"),
        "evidence_refs": list(cast(list[object], payload.get("evidence_refs"))),
    }
    record_sha = hashlib.sha256(json.dumps(record_material, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    stored_payload = dict(record_material)
    stored_payload["exact_approval_record_sha256"] = record_sha
    dto = _normalize_fresh_request_builder_downstream_consumption_exact_approval_record(stored_payload)
    if dto is None:
        return {"stored": False, "errors": [_error("payload", "invalid_normalized_record")], "dto": None}
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(dto, sort_keys=True, separators=(",", ":")) + "\n")
    return {"stored": True, "errors": [], "dto": dto}


