def _read_fresh_request_builder_downstream_consumption_idempotency_replay_guard_records(path: Path) -> tuple[list[dict[str, object]], int]:
    records: list[dict[str, object]] = []
    skipped_count = 0
    if not path.exists():
        return records, skipped_count
    with path.open("r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            if not line.strip():
                continue
            try:
                item = json.loads(line)
            except json.JSONDecodeError:
                skipped_count += 1
                continue
            if not isinstance(item, Mapping):
                skipped_count += 1
                continue
            normalized = _normalize_fresh_request_builder_downstream_consumption_idempotency_replay_guard_record(item)
            if normalized is None:
                skipped_count += 1
                continue
            records.append(normalized)
    return records, skipped_count


