    if not _validate_evidence_refs(payload.get("evidence_refs")):
        errors.append(_error("evidence_refs", "invalid_opaque_ref"))
    path = store_path or _default_fresh_request_builder_downstream_consumption_idempotency_replay_guard_record_store_path()
    existing, _ = _read_fresh_request_builder_downstream_consumption_idempotency_replay_guard_records(path)
    if any(record.get("idempotency_replay_guard_ref") == payload.get("idempotency_replay_guard_ref") for record in existing):
        errors.append(_error("idempotency_replay_guard_ref", "duplicate_idempotency_replay_guard_ref"))
    if any(record.get("operator_execution_approval_ref") == payload.get("operator_execution_approval_ref") for record in existing):
        errors.append(_error("operator_execution_approval_ref", "duplicate_operator_execution_approval_guard"))
