def _read_fresh_request_builder_downstream_consumption_payload_materialization_summary_review_gate_record_readback_reviews(path: Path) -> tuple[list[dict[str, object]], int]:
    records: list[dict[str, object]] = []
    skipped_count = 0
    if not path.exists():
        return records, skipped_count
    for line in path.read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        try:
            item = json.loads(line)
        except json.JSONDecodeError:
            skipped_count += 1
            continue
        if not isinstance(item, Mapping):
            skipped_count += 1
            continue
        normalized = _normalize_fresh_request_builder_downstream_consumption_payload_materialization_summary_review_gate_record_readback_review(item)
        if normalized is None:
            skipped_count += 1
            continue
        records.append(normalized)
    return records, skipped_count


def list_office_controlled_mutation_nas_keeper_fresh_request_builder_ledger_downstream_consumption_payload_materialization_summary_review_gate_record_readback_reviews(
    *,
    store_path: Path | None = None,
    readback_review_attestation_ref: str | None = None,
    limit: int = 50,
) -> dict[str, object]:
    errors: list[dict[str, str]] = []
    safe_ref: str | None = None
    if readback_review_attestation_ref is not None:
        if _office_disabled_runtime_dispatch_valid_prefixed_ref(readback_review_attestation_ref, "readbackreview-"):
            safe_ref = readback_review_attestation_ref
        else:
            errors.append(_error("readback_review_attestation_ref", "unsupported_ref_shape"))
    path = store_path or _default_fresh_request_builder_downstream_consumption_payload_materialization_summary_review_gate_record_readback_review_store_path()
    records, skipped_count = _read_fresh_request_builder_downstream_consumption_payload_materialization_summary_review_gate_record_readback_reviews(path)
    if safe_ref:
        records = [record for record in records if record.get("readback_review_attestation_ref") == safe_ref]
    records = records[-max(1, min(limit, 100)):]
    latest = records[-1] if records else None
    return {"found": bool(records) and not errors, "errors": errors, "record_count": len(records), "skipped_count": skipped_count, "latest_record": latest, "records": records}


def append_office_controlled_mutation_nas_keeper_fresh_request_builder_ledger_downstream_consumption_payload_materialization_summary_review_gate_record_readback_review(
    payload: object,
    *,
    readback_review_record_store_path: Path | None = None,
    store_path: Path | None = None,
) -> dict[str, object]:
    if not isinstance(payload, Mapping):
        return {"stored": False, "errors": [_error("payload", "invalid_payload_type")], "dto": None}
    source = get_office_controlled_mutation_nas_keeper_fresh_request_builder_ledger_downstream_consumption_payload_materialization_summary_review_gate_record_readback_review_record_readback(
        store_path=readback_review_record_store_path,
    )
    source_dto = source.get("dto") if isinstance(source.get("dto"), Mapping) else None
    source_map = cast(Mapping[str, object], source_dto) if isinstance(source_dto, Mapping) else {}
    errors: list[dict[str, str]] = []
    if not source.get("found") or not source_map:
        errors.append(_error("summary_review_gate_record_readback_review_record_ref", "readback_review_record_readback_not_found"))
    if not _office_disabled_runtime_dispatch_valid_prefixed_ref(payload.get("readback_review_attestation_ref"), "readbackreview-"):
        errors.append(_error("readback_review_attestation_ref", "unsupported_ref_shape"))
    for field in (
        "summary_review_gate_record_readback_review_record_ref",
        "summary_review_gate_record_readback_review_record_sha256",
        "payload_materialization_summary_review_gate_record_sha256",
    ):
        if payload.get(field) != source_map.get(field):
            errors.append(_error(field, "source_mismatch"))
    if payload.get("manual_attestation_outcome") != "attested_for_manual_review_only_no_consumption":
        errors.append(_error("manual_attestation_outcome", "unsupported_outcome"))
    for field in (
        "readback_verified",
        "source_checksum_attested",
        "safe_ref_chain_attested",
        "aggregate_counts_attested",
        "disabled_capabilities_attested",
    ):
        if payload.get(field) is not True:
            errors.append(_error(field, "must_be_true"))
    if not _is_opaque_id(payload.get("attested_by")):
        errors.append(_error("attested_by", "unsupported_identifier"))
    if not (isinstance(payload.get("attested_at"), str) and _ISO_UTC_RE.fullmatch(str(payload.get("attested_at")))):
        errors.append(_error("attested_at", "invalid_timestamp"))
    if not _is_safe_text(payload.get("safe_summary")):
        errors.append(_error("safe_summary", "unsafe_text"))
    if not _validate_evidence_refs(payload.get("evidence_refs")):
        errors.append(_error("evidence_refs", "unsupported_ref_shape"))
    if errors:
        return {"stored": False, "errors": errors, "dto": None}
    record = {
        "schema_version": 1,
        "readback_review_attestation_ref": payload.get("readback_review_attestation_ref"),
        "summary_review_gate_record_readback_review_record_ref": source_map.get("summary_review_gate_record_readback_review_record_ref"),
        "summary_review_gate_record_readback_review_record_sha256": source_map.get("summary_review_gate_record_readback_review_record_sha256"),
        "payload_materialization_summary_review_gate_record_sha256": source_map.get("payload_materialization_summary_review_gate_record_sha256"),
        "manual_attestation_outcome": payload.get("manual_attestation_outcome"),
        "readback_verified": True,
        "source_checksum_attested": True,
        "safe_ref_chain_attested": True,
        "aggregate_counts_attested": True,
        "disabled_capabilities_attested": True,
        "attested_by": payload.get("attested_by"),
        "attested_at": payload.get("attested_at"),
        "safe_summary": payload.get("safe_summary"),
        "evidence_refs": list(cast(list[object], payload.get("evidence_refs"))),
    }
    checksum_payload = json.dumps(record, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    record["readback_review_attestation_sha256"] = hashlib.sha256(checksum_payload).hexdigest()
    normalized = _normalize_fresh_request_builder_downstream_consumption_payload_materialization_summary_review_gate_record_readback_review(record)
    if normalized is None:
        return {"stored": False, "errors": [_error("payload", "normalization_failed")], "dto": None}
    path = store_path or _default_fresh_request_builder_downstream_consumption_payload_materialization_summary_review_gate_record_readback_review_store_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as fh:
        fh.write(json.dumps(record, sort_keys=True, separators=(",", ":"), ensure_ascii=False) + "\n")
    return {"stored": True, "errors": [], "dto": normalized}


