def _read_fresh_request_builder_downstream_consumption_manual_real_nas_write_boundary_records(path: Path) -> tuple[list[dict[str, object]], int]:
    records: list[dict[str, object]] = []
    skipped = 0
    if not path.exists():
        return records, skipped
    with path.open("r", encoding="utf-8") as handle:
        for line in handle:
            stripped = line.strip()
            if not stripped:
                continue
            try:
                item = json.loads(stripped)
            except json.JSONDecodeError:
                skipped += 1
                continue
            if not isinstance(item, dict):
                skipped += 1
                continue
            if item.get("mode") != "nas_keeper_fresh_request_builder_ledger_downstream_consumption_manual_real_nas_write_boundary_recorded":
                skipped += 1
                continue
            if not _office_disabled_runtime_dispatch_valid_prefixed_ref(item.get("manual_real_nas_write_boundary_ref"), "nasmanualboundary-"):
                skipped += 1
                continue
            if item.get("manual_real_nas_write_boundary_ready") is not True:
                skipped += 1
                continue
            records.append(item)
    return records, skipped


